#!/usr/bin/env node
/**
 * Differential fuzzer for the CORE happy path of test17.
 *
 *   reference: /workspace/dataset/test17_executable
 *   port:      node /output/test17.mjs
 *
 * Varies key byte-length in {16,24,32}, IV = 16 bytes, data length a multiple
 * of 16 from 0 to 32 blocks.  Characters are drawn from the full printable
 * ASCII range 0x20..0x7E (space .. '~'), which includes ' " \ space = -.
 *
 * Arguments are handed to spawnSync as an argv array with shell:false, so no
 * quoting is ever involved.
 */

import { spawnSync } from 'node:child_process';

const REF = '/workspace/dataset/test17_executable';
const PORT_ARGS = ['/output/test17.mjs'];
const NODE = process.execPath;

const TOTAL = Number(process.env.FUZZ_N || 520);
const SEED = Number(process.env.FUZZ_SEED || 0xC0FFEE);

/* ---------------------------------------------------------------- PRNG ---- */

function mulberry32(a) {
  return function rnd() {
    a |= 0;
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rnd = mulberry32(SEED);
const ri = (n) => Math.floor(rnd() * n);
const pick = (arr) => arr[ri(arr.length)];

/* ------------------------------------------------------------ generator --- */

// Full printable ASCII: 0x20 (space) .. 0x7E (~).  95 characters, all
// single-byte in UTF-8, so character count == byte count.
const ALPHABET = [];
for (let c = 0x20; c <= 0x7e; c += 1) ALPHABET.push(String.fromCharCode(c));

// Characters we like to over-sample because they are the ones that break naive
// quoting / repr implementations.
const SPICY = ["'", '"', '\\', ' ', '=', '-', '`', '$', '!', '*', '?', '~', '#',
  '&', '|', ';', '(', ')', '<', '>', '{', '}', '[', ']', '%', '^', '/', ',',
  '\t'.length ? "'" : "'"];

function randChar() {
  // 30% of the time force a "spicy" metacharacter, otherwise uniform printable.
  return rnd() < 0.3 ? pick(SPICY) : pick(ALPHABET);
}

function randStr(len) {
  let s = '';
  for (let i = 0; i < len; i += 1) s += randChar();
  return s;
}

/** A string of exactly `len` printable chars whose first char is not '-'. */
function randStrNoLeadingDash(len) {
  if (len === 0) return '';
  for (;;) {
    const s = randStr(len);
    if (s[0] !== '-') return s;
  }
}

/**
 * Build the argv array for one case.
 *
 * `form` selects how each option is spelled:
 *   'sep' -> ['--key', value]        (value must not begin with '-')
 *   'eq'  -> ['--key=value']         (value may begin with '-')
 * The option order is shuffled, since argparse accepts them in any order.
 */
function buildArgv({ key, iv, data, form, order }) {
  const parts = { key, iv, data };
  const argv = [];
  for (const name of order) {
    const value = parts[name];
    if (form[name] === 'eq') argv.push(`--${name}=${value}`);
    else argv.push(`--${name}`, value);
  }
  return argv;
}

const ORDERS = [
  ['key', 'iv', 'data'],
  ['key', 'data', 'iv'],
  ['iv', 'key', 'data'],
  ['iv', 'data', 'key'],
  ['data', 'key', 'iv'],
  ['data', 'iv', 'key'],
];

function makeCase(keyLen, blocks) {
  const form = {
    key: rnd() < 0.5 ? 'eq' : 'sep',
    iv: rnd() < 0.5 ? 'eq' : 'sep',
    data: rnd() < 0.5 ? 'eq' : 'sep',
  };
  const gen = (name, len) =>
    (form[name] === 'eq' ? randStr(len) : randStrNoLeadingDash(len));
  const key = gen('key', keyLen);
  const iv = gen('iv', 16);
  const data = gen('data', blocks * 16);
  const order = pick(ORDERS);
  return { key, iv, data, keyLen, blocks, argv: buildArgv({ key, iv, data, form, order }), form, order };
}

/** Systematic sweep over every (keyLen, blocks) pair, then random fill. */
function generateCases(total) {
  const keyLens = [16, 24, 32];
  const cases = [];
  for (const keyLen of keyLens) {
    for (let blocks = 0; blocks <= 32; blocks += 1) {
      cases.push(makeCase(keyLen, blocks));
      cases.push(makeCase(keyLen, blocks));
    }
  }
  while (cases.length < total) {
    cases.push(makeCase(pick(keyLens), ri(33)));
  }
  return cases;
}

/* ------------------------------------------------------------- spawning --- */

const SPAWN_OPTS = {
  shell: false,
  windowsHide: true,
  maxBuffer: 64 * 1024 * 1024,
  timeout: 60000,
  encoding: 'buffer',
};

function normErr(buf) {
  return (buf ? buf.toString('latin1') : '')
    .replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');
}

function runOnce(cmd, args) {
  const r = spawnSync(cmd, args, SPAWN_OPTS);
  return {
    status: r.status,
    signal: r.signal,
    spawnError: r.error ? String(r.error && r.error.message) : null,
    stdout: r.stdout || Buffer.alloc(0),
    stderr: r.stderr || Buffer.alloc(0),
  };
}

/** Run the reference, retrying the documented flaky null/signal exits. */
function runRef(args, attempts = 4) {
  let last = null;
  for (let i = 0; i < attempts; i += 1) {
    last = runOnce(REF, args);
    const flaky = last.spawnError !== null
      || last.status === null
      || (last.signal !== null && last.signal !== undefined);
    if (!flaky) return { ...last, refAttempts: i + 1 };
  }
  return { ...last, refAttempts: attempts };
}

function runPort(args) {
  return runOnce(NODE, [...PORT_ARGS, ...args]);
}

function compare(ref, port) {
  const diffs = [];
  if (!Buffer.from(ref.stdout).equals(Buffer.from(port.stdout))) diffs.push('stdout');
  if (normErr(ref.stderr) !== normErr(port.stderr)) diffs.push('stderr');
  if (ref.status !== port.status) diffs.push('exitCode');
  return diffs;
}

/* ----------------------------------------------------------------- main --- */

const cases = generateCases(TOTAL);
let matched = 0;
const mismatches = [];
const flakyNotes = [];
let bytesOut = 0;

const t0 = Date.now();
for (let i = 0; i < cases.length; i += 1) {
  const c = cases[i];
  const ref = runRef(c.argv);
  const port = runPort(c.argv);
  bytesOut += ref.stdout.length;
  if (ref.refAttempts > 1) {
    flakyNotes.push(`case ${i}: reference needed ${ref.refAttempts} attempts`);
  }

  let diffs = compare(ref, port);

  if (diffs.length > 0) {
    // Documented flakiness: re-run the exact same reference command 3 more
    // times before believing the failure.
    const reruns = [runOnce(REF, c.argv), runOnce(REF, c.argv), runOnce(REF, c.argv)];
    const agreeing = reruns.find((r) => compare(r, port).length === 0);
    if (agreeing) {
      flakyNotes.push(
        `case ${i}: first reference run disagreed (${diffs.join(',')}) but a re-run matched -> treated as reference flake`,
      );
      diffs = [];
    } else {
      mismatches.push({
        index: i,
        argv: c.argv,
        keyLen: c.keyLen,
        blocks: c.blocks,
        form: c.form,
        diffs,
        ref: {
          status: ref.status,
          signal: ref.signal,
          spawnError: ref.spawnError,
          stdout: ref.stdout.toString('latin1'),
          stderr: normErr(ref.stderr),
        },
        port: {
          status: port.status,
          signal: port.signal,
          spawnError: port.spawnError,
          stdout: port.stdout.toString('latin1'),
          stderr: normErr(port.stderr),
        },
        refReruns: reruns.map((r) => ({
          status: r.status,
          signal: r.signal,
          stdoutLen: (r.stdout || Buffer.alloc(0)).length,
          stdoutSha: hash(r.stdout || Buffer.alloc(0)),
        })),
      });
    }
  }

  if (diffs.length === 0) matched += 1;
  if ((i + 1) % 50 === 0) {
    process.stderr.write(
      `  ...${i + 1}/${cases.length} matched=${matched} mismatch=${mismatches.length} (${((Date.now() - t0) / 1000).toFixed(1)}s)\n`,
    );
  }
}

function hash(buf) {
  let h = 0x811c9dc5;
  for (const b of buf) { h ^= b; h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, '0');
}

/* --------------------------------------------------------------- report --- */

const report = {
  seed: SEED,
  totalCases: cases.length,
  matched,
  mismatchCount: mismatches.length,
  elapsedSeconds: Number(((Date.now() - t0) / 1000).toFixed(1)),
  refStdoutBytesCompared: bytesOut,
  coverage: {
    keyLens: [...new Set(cases.map((c) => c.keyLen))].sort((a, b) => a - b),
    blockCountsSeen: [...new Set(cases.map((c) => c.blocks))].sort((a, b) => a - b),
    argFormsSeen: [...new Set(cases.map((c) => `${c.form.key}/${c.form.iv}/${c.form.data}`))].sort(),
    leadingDashValues: cases.filter((c) => c.key[0] === '-' || c.iv[0] === '-' || c.data[0] === '-').length,
    valuesWithApostrophe: cases.filter((c) => (c.key + c.iv + c.data).includes("'")).length,
    valuesWithQuote: cases.filter((c) => (c.key + c.iv + c.data).includes('"')).length,
    valuesWithBackslash: cases.filter((c) => (c.key + c.iv + c.data).includes('\\')).length,
    valuesWithSpace: cases.filter((c) => (c.key + c.iv + c.data).includes(' ')).length,
    valuesWithEquals: cases.filter((c) => (c.key + c.iv + c.data).includes('=')).length,
    valuesWithDash: cases.filter((c) => (c.key + c.iv + c.data).includes('-')).length,
  },
  flakyNotes,
  mismatches,
};

process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);

